#include <iostream>
#include <string>
#include <typeinfo> // for typeid

template<typename T>
void f(const T& param) {
    // typeid on a template type parameter
    std::cout << "T is: " << typeid(T).name() << std::endl; 
    // typeid on the function parameter itself
    std::cout << "param is: " << typeid(param).name() << std::endl; 
}

int main() {
    const int x = 10;
    const int& rx = x;
    f(rx); // T deduced as 'int', not 'const int'. param's type is const int&, but typeid reports 'int'.
           // Output is implementation-defined, but it will show decayed types.
}
